import{_ as e,o,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const v=JSON.parse('{"title":"Reutilizar y revisar variables de ejecución","description":"","frontmatter":{"title":"Reutilizar y revisar variables de ejecución","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"0523914c120b4b083151d3d0cc7c2337a1d82156f7bcd0f1d05e5f4a594b2650","order":40},"headers":[],"relativePath":"es/user/automations/variables.md","filePath":"es/user/automations/variables.md","lastUpdated":1794611623000}'),r={name:"es/user/automations/variables.md"};function t(l,a,n,c,d,u){return o(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Reutilizar y revisar variables de ejecución <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;Reutilizar y revisar variables de ejecución {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Cambia una vez un valor compartido y reutilízalo en varias acciones. Necesitas <strong>Automations → Variables</strong> y un host compatible con las operaciones correspondientes. La edición tipada y las operaciones revisadas de Cloud dependen de sus capacidades; guardar localmente no requiere subir datos.</p><h2 id="save-a-local-value" tabindex="-1">Guardar un valor local <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;Guardar un valor local {#save-a-local-value}&quot;">​</a></h2><ol><li>Añade una variable llamada <code>showLabel</code>. Las claves comienzan con letra o guion bajo y admiten letras, números, puntos y guiones, hasta <code>64</code> caracteres. Evita claves repetidas.</li><li>Si está disponible la edición tipada, elige texto e introduce <code>Programa de la tarde</code>. También se admiten número, booleano, lista y secreto. Las listas utilizan un arreglo JSON de cadenas, como <code>[&quot;rojo&quot;, &quot;azul&quot;]</code>.</li><li>Pulsa <strong>Save</strong>. Un conflicto de revisión significa que la colección guardada cambió; vuelve a cargarla y compara con tu modificación prevista.</li><li>Utiliza el valor guardado en un campo de acción compatible con plantillas:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Prueba una acción que solo escriba un registro para inspeccionar el texto. Cambia <code>showLabel</code>, guarda y repite. Las definiciones existentes pueden reutilizar el valor actualizado sin importar de nuevo una plantilla.</li></ol><p>Los <code>params</code> se sustituyen al aplicar una plantilla; los <code>globals</code> se leen durante la ejecución. Una clave ausente produce texto vacío: verifica su escritura antes de usarla como destino o identificador. Las sugerencias del campo ofrecen rutas de evento apropiadas para el disparador.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Revisar cambios de Cloud por separado <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;Revisar cambios de Cloud por separado {#review-cloud-changes-separately}&quot;">​</a></h2><p>El control <strong>Changes</strong> de Variables ofrece operaciones nativas revisadas de envío, consulta, aplicación/adopción y retirada cuando el host las admite. Guarda primero la edición local, selecciona una comparación, inspecciona tipo y valor y elige explícitamente la dirección. Consultar una propuesta de Cloud es distinto de aplicarla localmente. Retirar un valor compartido también es distinto de borrar una fila local.</p><p>Los valores secretos o bloqueados se ocultan en las comparaciones y no pueden enviarse mediante esta ruta. No conviertas un secreto en texto ordinario para evitar el bloqueo.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, estado y recuperación {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Están disponibles las variables locales y el intercambio revisado según capacidades; guardar localmente nunca sube datos automáticamente. Las claves o valores inválidos y las revisiones antiguas bloquean el guardado. Corrige el campo señalado o vuelve a cargar antes de repetir. Para fallos de sesión, consulta <a href="./../cloud/account.html">cuenta de Cloud</a>; para comparaciones, <a href="./../cloud/changes.html">Changes</a>.</p>',13)])])}const b=e(r,[["render",t]]);export{v as __pageData,b as default};
